-- Family OS exercise catalog. We mint the UUID; wger is source + source_id only.
--> statement-breakpoint
CREATE TABLE workout_exercise_catalog (
  id uuid PRIMARY KEY,
  name text NOT NULL,
  category text NOT NULL,
  equipment_json jsonb NOT NULL DEFAULT '[]'::jsonb,
  source text NOT NULL,
  source_id text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT workout_exercise_catalog_name_check CHECK (char_length(name) BETWEEN 1 AND 80),
  CONSTRAINT workout_exercise_catalog_source_check CHECK (source IN ('wger'))
);
--> statement-breakpoint
CREATE UNIQUE INDEX workout_exercise_catalog_source_id_idx
  ON workout_exercise_catalog (source, source_id);
--> statement-breakpoint
CREATE INDEX workout_exercise_catalog_category_name_idx
  ON workout_exercise_catalog (category, name);
--> statement-breakpoint
--> statement-breakpoint
ALTER TABLE health_workout_exercises
  ADD COLUMN IF NOT EXISTS catalog_id uuid REFERENCES workout_exercise_catalog(id);
--> statement-breakpoint
CREATE INDEX IF NOT EXISTS health_workout_exercises_catalog_idx
  ON health_workout_exercises (catalog_id);
--> statement-breakpoint
CREATE TRIGGER workout_exercise_catalog_set_updated_at
  BEFORE UPDATE ON workout_exercise_catalog
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();
